source='''from collections import Counter


def transform(grid):
    """Project seeded fill rays inward from paired edge marker runs."""
    h, w = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]

    edge_counts = Counter()
    for r in range(h):
        for c in range(w):
            if r in (0, h - 1) or c in (0, w - 1):
                if grid[r][c] != background:
                    edge_counts[grid[r][c]] += 1
    marker = edge_counts.most_common(1)[0][0]
    fill = next(value for value, _ in counts.most_common()
                if value not in (background, marker))

    def runs(indices):
        groups = []
        for index in sorted(indices):
            if not groups or index > groups[-1][-1] + 1:
                groups.append([index])
            else:
                groups[-1].append(index)
        return groups

    candidates = []
    sides = {
        "top": runs(c for c in range(w) if grid[0][c] == marker),
        "bottom": runs(c for c in range(w) if grid[h - 1][c] == marker),
        "left": runs(r for r in range(h) if grid[r][0] == marker),
        "right": runs(r for r in range(h) if grid[r][w - 1] == marker),
    }
    for side, groups in sides.items():
        for group in groups:
            # Ignore single corner pixels counted again on an adjacent side.
            if len(group) >= 2:
                candidates.append((side, group))

    pairs = []
    opposite = {("top", "bottom"), ("bottom", "top"),
                ("left", "right"), ("right", "left")}
    for side_a, run_a in candidates:
        for side_b, run_b in candidates:
            if (side_a, side_b) in opposite and len(run_a) == len(run_b):
                pairs.append((side_a, run_a, side_b, run_b))

    if pairs:
        side_a, run_a, side_b, run_b = max(
            pairs, key=lambda pair: len(pair[1]) + len(pair[3]))
    else:
        side_a, run_a = candidates[0]
        side_b, run_b = None, []

    horizontal_runs = side_a in ("top", "bottom")
    active_offsets = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != fill:
                continue
            position = c if horizontal_runs else r
            if run_a[0] <= position <= run_a[-1]:
                active_offsets.add(position - run_a[0])
            if run_b and run_b[0] <= position <= run_b[-1]:
                active_offsets.add(position - run_b[0])

    output = [row[:] for row in grid]
    for side, run in ([(side_a, run_a)] +
                      ([(side_b, run_b)] if run_b else [])):
        for offset in active_offsets:
            position = run[offset]
            if side == "top":
                r, c, dr, dc = 0, position, 1, 0
            elif side == "bottom":
                r, c, dr, dc = h - 1, position, -1, 0
            elif side == "left":
                r, c, dr, dc = position, 0, 0, 1
            else:  # right
                r, c, dr, dc = position, w - 1, 0, -1

            rr, cc = r + dr, c + dc
            while 0 <= rr < h and 0 <= cc < w:
                if grid[rr][cc] == marker:
                    break
                if grid[rr][cc] == fill:
                    output[rr][cc] = 4
                    break
                output[rr][cc] = fill
                rr += dr
                cc += dc
    return output
